@Service
public class HireService {

    private final ApplicationRepository applications;
    private final PayrollClient payroll;

    public HireService(ApplicationRepository applications, PayrollClient payroll) {
        this.applications = applications;
        this.payroll = payroll;
    }

    @Transactional
    public void hire(long applicationId) throws PayrollException {
        Application application = applications.findById(applicationId).orElseThrow();
        application.setStatus("Hired");
        payroll.createEmployee(application); // throws PayrollException, a checked exception
    }
}

